
import axiosInstance from "../../utils/axiosInstance.js";
import axios from "axios";


const loginUser = async ({username, password}) => {
    const payload = {
        username: username,
        password: password
    }
    return await axiosInstance.post('auth/login.php', payload);
};

export default loginUser;

const baseURL = process.env.REACT_APP_API_BASE_URL;


export const logoutUser = async () => {
    try {
        await axiosInstance.post('auth/logout.php');
    } catch (error) {
        console.error("Logout failed", error);
    } finally {
        window.location.href = '/login';
    }
};


export const checkAuth = async () => {
    try {
        const response = await axios.get(baseURL+"auth/check.php", {
            withCredentials: true,
        });
        return true;
    } catch (err) {
        if (err.response?.status === 401) {
            // Try to refresh
            try {
                await axios.get(baseURL+"auth/refresh.php", {
                    withCredentials: true,
                });
                return true; // refreshed successfully!
            } catch (refreshErr) {
                console.error("Token refresh failed:", refreshErr);
                return false;
            }
        }
        return false;
    }
};




